package ai.interviewhq.api.question.repository;
import com.fasterxml.jackson.databind.ObjectMapper; import org.junit.jupiter.api.Test; import software.amazon.awssdk.services.dynamodb.DynamoDbClient; import software.amazon.awssdk.services.dynamodb.model.*; import java.util.List; import java.util.Map; import static org.junit.jupiter.api.Assertions.*; import static org.mockito.ArgumentMatchers.any; import static org.mockito.Mockito.*;
class DynamoDbQuestionRepositoryTest {
 @Test void detailUsesEntityLookupThenCanonicalItem(){DynamoDbClient c=mock(DynamoDbClient.class);when(c.getItem(any(GetItemRequest.class))).thenReturn(GetItemResponse.builder().item(Map.of("data",AttributeValue.builder().m(Map.of("experienceId",AttributeValue.builder().n("4").build(),"dedupeHash",AttributeValue.builder().s("abc").build())).build())).build()).thenReturn(GetItemResponse.builder().item(Map.of("data",AttributeValue.builder().m(Map.of("id",AttributeValue.builder().n("7").build(),"questionText",AttributeValue.builder().s("Q").build())).build())).build());var r=new DynamoDbQuestionRepository(c,new ObjectMapper(),"table").findById(7);assertTrue(r.found());assertEquals("Q",r.data().get("questionText"));var captor=org.mockito.ArgumentCaptor.forClass(GetItemRequest.class);verify(c,times(2)).getItem(captor.capture());assertEquals("QUESTION_ID#7",captor.getAllValues().get(0).key().get("pk").s());assertEquals("ENTITY",captor.getAllValues().get(0).key().get("sk").s());assertEquals("EXPERIENCE#4",captor.getAllValues().get(1).key().get("pk").s());assertEquals("QUESTION#abc",captor.getAllValues().get(1).key().get("sk").s());}
 @Test void experienceListUsesQueryNotScanAndReturnsCursor(){DynamoDbClient c=mock(DynamoDbClient.class);when(c.query(any(QueryRequest.class))).thenReturn(QueryResponse.builder().items(List.of()).lastEvaluatedKey(Map.of("pk",AttributeValue.builder().s("EXPERIENCE#4").build(),"sk",AttributeValue.builder().s("QUESTION#abc").build())).build());var r=new DynamoDbQuestionRepository(c,new ObjectMapper(),"table");var page=r.listByExperience(4,25,Map.of());var captor=org.mockito.ArgumentCaptor.forClass(QueryRequest.class);verify(c).query(captor.capture());assertTrue(captor.getValue().keyConditionExpression().contains("begins_with"));assertEquals("EXPERIENCE#4",captor.getValue().expressionAttributeValues().get(":pk").s());assertEquals("QUESTION#",captor.getValue().expressionAttributeValues().get(":sk").s());assertEquals(Map.of("pk","EXPERIENCE#4","sk","QUESTION#abc"),page.lastEvaluatedKey());verify(c,never()).scan(any(ScanRequest.class));}
 @Test void nullExperienceDoesNotQuery(){DynamoDbClient c=mock(DynamoDbClient.class);var r=new DynamoDbQuestionRepository(c,new ObjectMapper(),"table");var page=r.listByExperience(null,25,Map.of());assertTrue(page.items().isEmpty());verify(c,never()).query(any(QueryRequest.class));}
}